import Foundation
import OpenUILang
import SwiftUI

/// Data generated by scripts/catalog.mjs from the pinned upstream Zod library.
/// No native schema/validation rules are authored here.
enum OpenUIReference {
  static let catalog: JSONValue = {
    guard
      let url = NativeControlResources.bundle.url(
        forResource: "upstream-catalog", withExtension: "json"),
      let source = try? String(contentsOf: url, encoding: .utf8),
      let catalog = try? parseJSONPreservingOrder(source)
    else {
      preconditionFailure("Missing packaged upstream component catalog")
    }
    return catalog
  }()
  static let definitions: [DefinedComponent] = (catalog.field("components")?.arrayItems ?? [])
    .map { c in
      DefinedComponent(
        name: c.field("name")!.stringValue!, description: c.field("description")!.stringValue!,
        params: (c.field("params")?.arrayItems ?? []).map { p in
          ParamDef(
            name: p.field("name")!.stringValue!, required: p.field("required") == .boolean(true),
            hasDefault: p.field("hasDefault") == .boolean(true),
            defaultValue: jsonToValue(p.field("defaultValue") ?? .null),
            isBindable: p.field("isBindable") == .boolean(true), schema: p.field("schema"))
        })
    }
  static let groups: [ComponentGroup] =
    LibrarySpec(json: catalog.field("spec")!).componentGroups ?? []
  static func component<Content: View>(
    _ name: String, @ViewBuilder content: @escaping (OpenUIComponentContext) -> Content
  ) -> OpenUIComponent {
    guard let definition = definitions.first(where: { $0.name == name }) else {
      preconditionFailure("Component absent from pinned upstream catalog: " + name)
    }
    return OpenUIComponent(definition, content: content)
  }
}
